/**
 * Copies the tutorial catalog and its screenshots into the money2time-web
 * repository, so money2time.com and the app never drift.
 *
 *   features/tutorials/content/*  ->  src/lib/tutorials.generated.ts
 *   assets/tutorials/*.png        ->  public/tutorials/*.png
 *
 * This repo is the source of truth: the catalog is written here (in English,
 * see features/tutorials/content/types.ts) and the website consumes it. Never
 * hand-edit the generated file on the web side, it is overwritten on the next
 * run.
 *
 *   node scripts/sync-tutorials-web.mjs                    # ../money2time-web
 *   node scripts/sync-tutorials-web.mjs --web ../elsewhere
 *   MONEY2TIME_WEB_DIR=... node scripts/sync-tutorials-web.mjs
 *
 * Run it after changing anything under `features/tutorials/content/` or
 * re-running `scripts/annotate-tutorials.mjs`.
 */
import { promises as fs } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const ASSET_DIR = path.join(ROOT, 'assets/tutorials');
const CONTENT_DIR = path.join(ROOT, 'features/tutorials/content');

function resolveWebDir() {
  const flag = process.argv.indexOf('--web');
  if (flag >= 0 && process.argv[flag + 1]) return path.resolve(process.argv[flag + 1]);
  if (process.env.MONEY2TIME_WEB_DIR) return path.resolve(process.env.MONEY2TIME_WEB_DIR);
  return path.resolve(ROOT, '../money2time-web');
}

/**
 * Evaluates one content file as JavaScript. The content files are plain data
 * with no imports beyond the shared `type`, so stripping the type import and
 * the `: Tutorial[]` annotation leaves something a dynamic `import()` of a
 * data: URL can run. That keeps this script a dependency-free `node` run, like
 * every other script in `scripts/`.
 */
async function evaluate(source, exportName) {
  const stripped = source
    .replace(/^import type .*$/gm, '')
    .replace(/:\s*Tutorial\[\]\s*=/, ' =')
    .replace(new RegExp(`^export const ${exportName}\\b`, 'm'), 'export const EXPORTED');
  const module = await import(
    `data:text/javascript;base64,${Buffer.from(stripped, 'utf8').toString('base64')}`
  );
  return module.EXPORTED;
}

async function loadCatalog() {
  const files = (await fs.readdir(CONTENT_DIR))
    .filter((file) => file.endsWith('.ts'))
    .filter((file) => !['types.ts', 'tutorials.ts', 'images.generated.ts'].includes(file))
    .sort();

  const tutorials = [];
  for (const file of files) {
    const source = await fs.readFile(path.join(CONTENT_DIR, file), 'utf8');
    const name = source.match(/^export const (\w+)/m)?.[1];
    tutorials.push(...(await evaluate(source, name)));
  }
  return tutorials;
}

/**
 * Read out of types.ts rather than duplicated here, so the order cannot drift.
 * Picked out with a regex rather than evaluated, because types.ts is the one
 * content file that is real TypeScript (`export type`, `export interface`).
 */
async function loadCategoryOrder() {
  const source = await fs.readFile(path.join(CONTENT_DIR, 'types.ts'), 'utf8');
  const literal = source.match(/TUTORIAL_CATEGORY_IDS[^=]*=\s*\[([^\]]*)\]/)?.[1];
  const ids = [...(literal ?? '').matchAll(/'([^']+)'/g)].map((match) => match[1]);
  if (ids.length === 0) throw new Error('Could not read TUTORIAL_CATEGORY_IDS from types.ts');
  return ids;
}

function sortCatalog(tutorials, order) {
  return [...tutorials].sort((a, b) => order.indexOf(a.category) - order.indexOf(b.category));
}

function renderCatalog(tutorials, CATEGORY_ORDER) {
  const body = JSON.stringify(tutorials, null, 2)
    .split('\n')
    .map((line) => `  ${line}`)
    .join('\n')
    .trim();

  return `// AUTO-GENERATED by the app repo's scripts/sync-tutorials-web.mjs — do not edit.
// Source of truth: money2time/features/tutorials/content/*.ts
// Screenshots live in public/tutorials/<image>.png, copied by the same script.

export type TutorialCategoryId =
${CATEGORY_ORDER.map((id) => `  | "${id}"`).join('\n')};

export const TUTORIAL_CATEGORY_IDS: TutorialCategoryId[] = [
${CATEGORY_ORDER.map((id) => `  "${id}",`).join('\n')}
];

export type TutorialStep = {
  /** File name (no extension) under public/tutorials. */
  image: string | null;
  title: string;
  body: string;
};

export type Tutorial = {
  id: string;
  category: TutorialCategoryId;
  title: string;
  summary: string;
  keywords: string[];
  /** Set when the feature only exists on one platform. */
  platform?: "ios";
  /** Set when the feature needs Pro. */
  pro?: boolean;
  steps: TutorialStep[];
};

export const TUTORIALS: Tutorial[] = ${body};
`;
}

async function copyImages(webDir, tutorials) {
  const outDir = path.join(webDir, 'public/tutorials');
  await fs.rm(outDir, { recursive: true, force: true });
  await fs.mkdir(outDir, { recursive: true });

  const names = tutorials.flatMap((tutorial) =>
    tutorial.steps.map((step) => step.image).filter(Boolean),
  );
  for (const name of names) {
    await fs.copyFile(path.join(ASSET_DIR, `${name}.png`), path.join(outDir, `${name}.png`));
  }
  return names.length;
}

async function main() {
  const webDir = resolveWebDir();
  try {
    await fs.access(path.join(webDir, 'package.json'));
  } catch {
    console.error(`No money2time-web checkout at ${webDir}. Pass --web <path>.`);
    process.exitCode = 1;
    return;
  }

  const order = await loadCategoryOrder();
  const tutorials = sortCatalog(await loadCatalog(), order);
  const catalogPath = path.join(webDir, 'src/lib/tutorials.generated.ts');
  await fs.writeFile(catalogPath, renderCatalog(tutorials, order));
  const copied = await copyImages(webDir, tutorials);

  console.warn(
    `Synced ${tutorials.length} tutorial(s) and ${copied} screenshot(s) to ${path.relative(ROOT, webDir)}`,
  );
}

await main();
